    /// <summary>
    /// Delivers all ten exact approved images only after real consumption evidence earns their identities.
    /// </summary>
    /// <returns>A task completing after earned reads, transparency, wire batches and acknowledgement are checked.</returns>
    [Fact]
    public async Task ApprovedItemArtworkSurvivesEarnedAccessAndNotificationDelivery()
    {
        Dictionary<Guid, string> expected = JsonSerializer.Deserialize<Dictionary<Guid, string>>(_assignedItemHashes)!;
        using TestDirectory directory = new();
        await using GameplayCollectionStore store = new(directory.Path);
        Assert.Empty(await store.GetAchievementIconsAsync(expected.Keys));
        JsonElement consumption = JsonSerializer.SerializeToElement(new { item_id = _potion, disposition = _consumedDisposition, quantity = 25000, battle_entry_owner = _player, current_controller = _player });
        await store.AcceptBatchAsync(Batch(_stream, [Occurrence(_resourceDisposal, consumption, 1)]));
        var earned = await store.GetAchievementsAsync();
        var icons = await store.GetAchievementIconsAsync(expected.Keys);
        Assert.Equal(expected.Keys.Order(), icons.Keys.Order());
        foreach (var assignment in expected)
        {
            var icon = icons[assignment.Key];
            byte[] pixels = Convert.FromBase64String(icon.Pixels);
            Assert.Equal(_achievementDisplaySize, icon.Width);
            Assert.Equal(_achievementDisplaySize, icon.Height);
            Assert.Equal(assignment.Value, Convert.ToHexString(SHA256.HashData(pixels)));
            Assert.Contains(Enumerable.Range(0, icon.Width * icon.Height), index => pixels[index * 4 + 3] == 0);
            Assert.Contains(Enumerable.Range(0, icon.Width * icon.Height), index => pixels[index * 4 + 3] == 255);
            Assert.NotEqual(AchievementIconPack.Shared.Fallback.ImageDataUri, icon.ImageDataUri);
        }

        TrackerDiagnosticsStore diagnostics = new();
        using TrackerRequestSession session = new(diagnostics);
        using MemoryStream bytes = new();
        await using TrackerMessageWriter writer = new(bytes, leaveOpen: true);
        session.Connect(writer);
        using GameplayCollectionReceiver receiver = new(store, session, diagnostics, true);
        HashSet<Guid> delivered = [];
        for (int poll = 0; poll < expected.Count && !expected.Keys.All(delivered.Contains); poll++)
        {
            bytes.SetLength(0);
            await receiver.ProcessAsync(TrackerMessageFactory.CreateEvent(GameplayCollectionProtocol.AchievementPoll, poll + 1, new { }), CancellationToken.None);
            string wire = Encoding.UTF8.GetString(bytes.ToArray()).Trim();
            Assert.InRange(wire.Length, 1, TrackerProtocol.MaximumMessageCharacters);
            TrackerMessage message = TrackerMessageCodec.Deserialize(wire);
            var notices = message.Payload.GetProperty(_unlocksKey);
            Assert.InRange(notices.GetArrayLength(), 1, GameplayCollectionProtocol.MaximumAchievementNotices);
            HashSet<Guid> acknowledged = [];
            foreach (var notice in notices.EnumerateArray())
            {
                Guid id = notice.GetProperty(_assignedNoticeIdentity).GetGuid();
                acknowledged.Add(id);
                if (!expected.TryGetValue(id, out string? hash))
                    continue;

                Assert.Equal(hash, Convert.ToHexString(SHA256.HashData(notice.GetProperty(_iconKey).GetProperty(_pixelsKey).GetBytesFromBase64())));
                delivered.Add(id);
            }

            await store.AcknowledgeAchievementsAsync(acknowledged);
        }

        Assert.Equal(expected.Keys.Order(), delivered.Order());
        Assert.Equal(earned, await store.GetAchievementsAsync());
        Assert.Empty(Directory.EnumerateFiles(directory.Path, _assignedImagePattern, SearchOption.AllDirectories));
    }

    /// <summary>
    /// Checks approved stage images against their pixel snapshots without granting public access to locked artwork.
    /// </summary>
    /// <returns>A task completing after exact stage pixels, alpha and earned-only access are checked.</returns>
    [Fact]
    public async Task ApprovedStageArtworkMatchesExactMappings()
    {
        Dictionary<Guid, string> expected = JsonSerializer.Deserialize<Dictionary<Guid, string>>(_assignedStageHashes)!;
        HashSet<Guid> known = [.. new AchievementPack().Nodes.Select(node => node.Id)];
        using TestDirectory directory = new();
        await using GameplayCollectionStore store = new(directory.Path);
        Assert.Empty(await store.GetAchievementIconsAsync(expected.Keys));
        foreach (var assignment in expected)
        {
            Assert.Contains(assignment.Key, known);
            var icon = AchievementIconPack.Shared.ForEarned(assignment.Key);
            byte[] pixels = Convert.FromBase64String(icon.Pixels);
            Assert.Equal(_achievementDisplaySize, icon.Width);
            Assert.Equal(_achievementDisplaySize, icon.Height);
            Assert.Equal(assignment.Value, Convert.ToHexString(SHA256.HashData(pixels)));
            Assert.Contains(Enumerable.Range(0, icon.Width * icon.Height), index => pixels[index * 4 + 3] == 0);
            Assert.Contains(Enumerable.Range(0, icon.Width * icon.Height), index => pixels[index * 4 + 3] == 255);
        }

        Assert.Empty(await store.GetAchievementIconsAsync(expected.Keys));
        Assert.Empty(await store.GetAchievementsAsync());
        Assert.Empty(Directory.EnumerateFiles(directory.Path, _assignedImagePattern, SearchOption.AllDirectories));
    }
}
